// src/index.ts
import { parseHTML } from "linkedom";
import { join as join2 } from "node:path";
import { relative as relativeNormalized2 } from "node:path/posix";

// src/rendering.ts
import { join, relative, dirname } from "node:path";
import { relative as relativeNormalized } from "node:path/posix";
import { writeFile, mkdir } from "node:fs/promises";
import YAML from "yaml";
import pc from "picocolors";
async function writeIndexJson(outDir, knowledgeDir, groups) {
  const file = join(knowledgeDir, "index.json");
  await mkdir(dirname(file), { recursive: true });
  await writeFile(file, JSON.stringify(Object.keys(groups).map((groupName) => "/" + relativeNormalized(outDir, getGroupPath(knowledgeDir, groupName)))));
  printFileWriteSuccess(file);
}
async function writeKnowledgeFile(knowledgeDir, groupName, files) {
  const file = getGroupPath(knowledgeDir, groupName);
  await mkdir(dirname(file), { recursive: true });
  await writeFile(file, files.map(renderKnowledgeContext).join(`

`));
  printFileWriteSuccess(file);
}
function renderKnowledgeContext(ctx) {
  const frontmatter = {
    url: ctx.pathname
  };
  if (ctx.pageTitle !== ctx.siteTitle && ctx.pageTitle) {
    frontmatter.title = ctx.pageTitle;
  }
  if (ctx.pageDescription !== ctx.siteDescription && ctx.pageDescription) {
    frontmatter.description = ctx.pageDescription;
  }
  return `---
${YAML.stringify(frontmatter).trim()}
---

${ctx.md.trim()}`;
}
function printFileWriteSuccess(file) {
  console.log(`${pc.green("✓")} ${pc.dim("[knowledge]")} generated ${pc.cyan(relative(process.cwd(), file))}`);
}
function getGroupPath(knowledgeDir, groupName) {
  return join(knowledgeDir, `${groupName}.txt`);
}

// src/html-to-md.ts
import { NodeHtmlMarkdown } from "node-html-markdown";
function createHtmlToMdConverter() {
  const postprocessCustomBlock = (ctx) => {
    if (!ctx.node.classList.contains("custom-block"))
      return;
    const type = ["info", "tip", "warning", "danger", "details"].find((type2) => ctx.node.classList.contains(type2)) ?? "unknown";
    const titleNode = ctx.node.querySelector(".custom-block-title, summary");
    const title = titleNode?.textContent ? htmlToMd(titleNode.textContent) : undefined;
    const children = [];
    ctx.node.querySelectorAll(":scope > *:not(.custom-block-title, summary)").forEach((child) => void children.push(child.outerHTML));
    const content = htmlToMd(children.join(`
`));
    const isCustomTitle = title?.toLowerCase() !== type.toLowerCase();
    if (isCustomTitle)
      return `:::${type} ${title}
${content}
:::`;
    return `:::${type}
${content}
:::`;
  };
  const postprocessShikiCodeBlock = (ctx) => {
    if (!ctx.node.classList.toString().includes("language-"))
      return;
    const langNode = ctx.node.querySelector(".lang");
    const lang = langNode?.textContent ?? "";
    const contentNode = ctx.node.querySelector("pre");
    const content = contentNode ? htmlToMd(contentNode.outerHTML) : "";
    return content.replace("```\n", `\`\`\`${lang}
`);
  };
  const postprocessCodeGroup = (ctx) => {
    if (!ctx.node.classList.contains("vp-code-group"))
      return;
    const tabNodes = ctx.node.querySelectorAll(".tabs > label");
    const blockNodes = ctx.node.querySelectorAll(".blocks > div");
    const titles = [];
    tabNodes.forEach((tab) => titles.push(tab.textContent));
    const codeBlocks = [];
    blockNodes.forEach((child) => codeBlocks.push(htmlToMd(child.outerHTML)));
    return `:::code-group

` + codeBlocks.map((block, i) => {
      if (titles[i])
        return block.replace(`
`, ` [${titles[i]}]
`) + `
`;
      return block + `
`;
    }).join(`
`) + `
:::`;
  };
  const nhm = new NodeHtmlMarkdown({}, {
    div: {
      postprocess(ctx) {
        const customBlock = postprocessCustomBlock(ctx);
        if (customBlock)
          return customBlock;
        const codeBlock = postprocessShikiCodeBlock(ctx);
        if (codeBlock)
          return codeBlock;
        const codeGroup = postprocessCodeGroup(ctx);
        if (codeGroup)
          return codeGroup;
        return ctx.content;
      }
    },
    details: {
      postprocess(ctx) {
        const customBlock = postprocessCustomBlock(ctx);
        if (customBlock)
          return customBlock;
        return ctx.content;
      },
      surroundingNewlines: true
    }
  });
  const htmlToMd = nhm.translate.bind(nhm);
  return htmlToMd;
}

// src/index.ts
import pc2 from "picocolors";
function knowledge(options) {
  const htmlToMd = createHtmlToMdConverter();
  const results = [];
  const warnings = [];
  const DEFAULT_LAYOUT_SELECTORS = {
    undefined: "main",
    home: ".VPHome"
  };
  const ignore = new Set(options?.ignore);
  ignore.add("404.md");
  return {
    extends: options?.extends,
    head: options?.serverUrl ? [
      [
        "script",
        {
          defer: "true",
          async: "true",
          src: `${options.serverUrl}/ask-ai.js`
        }
      ]
    ] : [],
    transformHtml(code, id, ctx) {
      if (ignore.has(ctx.page))
        return;
      try {
        const { document } = parseHTML(code);
        const selector = options?.pageSelectors?.[ctx.page] ?? options?.layoutSelectors?.[ctx.pageData.frontmatter.layout] ?? options?.selector ?? DEFAULT_LAYOUT_SELECTORS[ctx.pageData.frontmatter.layout ?? "undefined"];
        if (selector == null) {
          warnings.push([
            pc2.cyan(ctx.page),
            `No selector found, falling back to "body". You probably want to provide a custom selector for this page/layout to filter out navigation`
          ]);
        }
        const root = document.querySelector(selector ?? "body");
        if (!root) {
          warnings.push([
            pc2.cyan(ctx.page),
            `Selector "${selector}" did not match any elements`
          ]);
          return;
        }
        const md = htmlToMd(root.innerHTML);
        if (!md) {
          warnings.push([
            pc2.cyan(ctx.page),
            `Empty page, no knowledge to extract`
          ]);
          return;
        }
        let pathname = `/${relativeNormalized2(ctx.siteConfig.outDir, id).replace("index.html", "")}`;
        if (ctx.siteConfig.cleanUrls) {
          pathname = pathname.replace(".html", "");
        }
        results.push({
          sourceMdFile: ctx.page,
          pageTitle: ctx.pageData.title,
          pageDescription: ctx.pageData.description,
          siteTitle: ctx.siteData.title,
          siteDescription: ctx.siteData.description,
          pathname,
          md
        });
      } catch (err) {
        warnings.push([pc2.cyan(ctx.page), `Failed to parse HTML:`, err]);
      }
    },
    async buildEnd(siteConfig) {
      const knowledgeDir = join2(siteConfig.outDir, options?.dir ?? "knowledge");
      const pageOrderMap = getPageOrder(siteConfig);
      results.sort((a, b) => {
        const aOrder = pageOrderMap[a.sourceMdFile] ?? Number.MAX_SAFE_INTEGER;
        const bOrder = pageOrderMap[b.sourceMdFile] ?? Number.MAX_SAFE_INTEGER;
        const orderDiff = aOrder - bOrder;
        if (orderDiff !== 0)
          return orderDiff;
        return a.sourceMdFile.localeCompare(b.sourceMdFile);
      });
      const groups = groupPaths(options?.paths, results);
      for (const [groupName, files] of Object.entries(groups)) {
        await writeKnowledgeFile(knowledgeDir, groupName, files);
      }
      await writeIndexJson(siteConfig.outDir, knowledgeDir, groups);
      if (warnings.length > 0) {
        console.warn(`${pc2.yellow("‼")} ${pc2.dim("[knowledge]")} Warnings: ${warnings.length}`);
        warnings.forEach((warning) => {
          console.warn(`  ${pc2.dim("-")}`, ...warning);
        });
      }
    }
  };
}
function groupPaths(paths, files) {
  const groups = {};
  const bases = Object.keys(paths ?? {}).sort((a, b) => b.length - a.length);
  for (const file of files) {
    const base = bases.find((base2) => file.pathname.startsWith(base2)) ?? "/";
    const output = paths?.[base ?? ""] ?? "docs";
    groups[output] ??= [];
    groups[output].push(file);
  }
  return groups;
}
function getPageOrder(siteConfig) {
  const pageOrderMap = {};
  function traverseItems(items, prefix = "") {
    const paths = [];
    if (Array.isArray(items)) {
      items.forEach((item) => {
        const link = typeof item === "string" ? item : item.link;
        if (link) {
          if (link.startsWith("/"))
            paths.push(link);
          else
            paths.push(prefix + link);
        }
        if (item.items) {
          const newPrefix = item.base?.startsWith("/") ? item.base : prefix + (item.base ?? "");
          paths.push(...traverseItems(item.items, newPrefix));
        }
      });
    } else if (typeof items === "object" && items) {
      paths.push(...traverseItems(Object.values(items).flat()));
    }
    return paths;
  }
  const sidebarPaths = traverseItems(siteConfig.site?.themeConfig?.sidebar ?? []);
  const allPaths = [
    "index.md",
    ...sidebarPaths
  ].map((path) => path.endsWith(".md") ? path : path + ".md").map((path) => path.startsWith("/") ? path.substring(1) : path);
  allPaths.forEach((path, index) => {
    pageOrderMap[path] = index;
  });
  return pageOrderMap;
}
export {
  getPageOrder,
  knowledge as default
};
